<?php
require_once __DIR__.'/app/lib/Db.php';
require_once __DIR__.'/app/lib/Security.php';
Security::start();$csrf=Security::csrf();$pdo=Db::pdo();
$cats=$pdo->query("SELECT id,name FROM categories WHERE is_active=1 ORDER BY name")->fetchAll();
$esc=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Suggest Software | TechSelectAI</title><style>body{font-family:system-ui;background:#f6f9fb;color:#17324d;margin:0}.wrap{max-width:900px;margin:auto;padding:34px 20px}.card{background:#fff;border:1px solid #dfe8ee;border-radius:16px;padding:24px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}label{display:block;font-size:13px;font-weight:700;margin-bottom:5px}input,select,textarea{width:100%;box-sizing:border-box;padding:10px;border:1px solid #cbd8e1;border-radius:9px}textarea{min-height:88px}.full{grid-column:1/-1}.note{color:#64748b;line-height:1.55}.alert{display:none;margin:14px 0;padding:12px;border-radius:10px;background:#fff5db}.ok{background:#eaf8f3}button{padding:11px 15px;border:0;border-radius:10px;background:#123b67;color:#fff;font-weight:800}@media(max-width:650px){.grid{grid-template-columns:1fr}}</style></head><body><div class="wrap"><div class="card"><h1>Suggest software to TechSelectAI</h1><p class="note">Vendors can submit software they own or develop, and buyers can suggest missing products. Submission does not guarantee listing and never influences TechSelectAI scores or recommendations.</p><form id="f"><div class="grid"><div><label>Submission type</label><select name="submission_type"><option value="user_suggestion">Suggest a missing product</option><option value="vendor_submission">Vendor submission</option></select></div><div><label>Product name *</label><input name="product_name" required maxlength="190"></div><div><label>Vendor / company</label><input name="vendor_name" maxlength="190"></div><div><label>Official website</label><input name="official_website" type="url"></div><div><label>Category</label><select name="category_id"><option value="">Not sure</option><?php foreach($cats as $c): ?><option value="<?=intval($c['id'])?>"><?=$esc($c['name'])?></option><?php endforeach ?></select></div><div><label>Submitter email</label><input name="submitter_email" type="email"></div><div class="full"><label>Short description</label><textarea name="short_description"></textarea></div><div><label>Pricing URL</label><input name="pricing_url" type="url"></div><div><label>Documentation URL</label><input name="documentation_url" type="url"></div><div><label>Security / compliance URL</label><input name="security_url" type="url"></div><div><label>Integrations URL</label><input name="integrations_url" type="url"></div><div class="full"><label>Deployment options</label><input name="deployment_options" placeholder="SaaS, self-hosted, hybrid..."></div><div class="full"><label>Supporting notes / evidence</label><textarea name="supporting_notes"></textarea></div><div class="full"><label>Reference asset URL</label><input name="reference_asset_url" type="url"></div></div><div id="alert" class="alert"></div><p><button type="submit">Submit for review</button></p></form></div></div><script>const csrf=<?='"'.$esc($csrf).'"'?>;const f=document.getElementById('f'),a=document.getElementById('alert');async function dup(){const n=f.product_name.value.trim();if(!n)return;const w=f.official_website.value.trim();const r=await fetch('/api/software-submissions?name='+encodeURIComponent(n)+'&website='+encodeURIComponent(w));const j=await r.json();if(j.duplicate){a.style.display='block';a.className='alert';a.innerHTML='This product may already exist as <strong>'+j.duplicate.product.name+'</strong>. Please use Suggest an update or Add to company portfolio instead of creating a duplicate.';}else a.style.display='none';}f.product_name.addEventListener('blur',dup);f.official_website.addEventListener('blur',dup);f.addEventListener('submit',async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(f).entries());const r=await fetch('/api/software-submissions',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:JSON.stringify(data)});const j=await r.json();a.style.display='block';if(r.ok){a.className='alert ok';a.textContent=j.status==='duplicate_detected'?'Submitted, but we detected an existing product. A reviewer will route this as an update/portfolio request.':'Submitted for TechSelectAI review. No public listing has been created.';f.reset();}else{a.className='alert';a.textContent=j.error||'Submission failed';}});</script></body></html>